// =========================================
// Helper Functions
// =========================================

// Get all words from one lesson
function getWordsForLesson(lessonName) {
    return VOCAB_DATA.filter(v => v.lesson === lessonName);
}

// Get one word (first occurrence)
function getWord(word) {
    return VOCAB_DATA.find(v => v.word === word);
}

// Get every entry for a word
function getWordEntries(word) {
    return VOCAB_DATA.filter(v => v.word === word);
}

// Get the lesson where a word first appears
function getFirstAppearance(word) {
    const entry = getWord(word);
    return entry ? entry.lesson : null;
}

// Get every unique lesson
function getLessons() {
    return [...new Set(VOCAB_DATA.map(v => v.lesson))];
}

// Get every unique word
function getUniqueWords() {
    return [...new Set(VOCAB_DATA.map(v => v.word))];
}

// Search
function searchVocabulary(query) {

    query = query.toLowerCase();

    return VOCAB_DATA.filter(item =>
        item.word.includes(query) ||
        item.type1.toLowerCase().includes(query) ||
        item.type2.toLowerCase().includes(query)
    );

}

// Remove "" from lesson names
function getLessonTitle(lessonName) {
    return lessonName.replace(/\$/i, "");
}